    for r in range(h):
        marks = [c for c, value in enumerate(grid[r]) if value == marker]
        for a, b in zip(marks, marks[1:]):
            for c in range(a + 1, b):
                if grid[r][c] != marker:
                    out[r][c] = 3
    for c in range(w):
